// Fonction pour obtenir une traduction
export const getEditorText = (lang, path) => {
  const keys = path.split('.');
  let value = editorTranslations[lang] || editorTranslations.fr;
  
  for (const key of keys) {
    value = value?.[key];
    if (!value) return path;
  }
  
  return value;
};
